            <p className="text-sm text-muted-foreground">Your closet is empty.</p>
            <Link
              href="/closet/upload"
              className="rounded-[12px] bg-foreground px-6 py-3 text-sm font-semibold text-canvas"
            >
              Add your first piece
            </Link>
          </div>
        ) : (
          <ClosetGrid items={grid} />
        )}
      </main>
      <MobileNav />
    </div>
  );
}

