4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { personalBand, applyFormalityOverride } from "@/lib/generator/rules";
8	import { buildCandidates, missingCategory, type CandidateItem } from "@/lib/generator/candidates";
9	import { rankTopN } from "@/lib/generator/rank";
10	import { rerank } from "@/lib/generator/rerank";
11	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
12	import { localDateFor } from "@/lib/outfits/local-date";
13	import { loadDailyLooks, saveDailyLooks } from "@/lib/outfits/daily";
14	import { reassembleLooks } from "@/lib/outfits/reassemble";
15	import { assertCanGenerate } from "@/lib/outfits/quota";
16	import {
17	  resolveLocation,
18	  roundCoord,
19	  LocationInputSchema,
20	  type LocationSource,
21	} from "@/lib/weather/location";
22	import type {
23	  GenerateResult,
24	  Look,
25	  LookPiece,
26	  UiOccasion,
27	  WeatherPayload,
28	} from "@/lib/generator/types";
29	
30	function currentSeason(d: Date): string {
31	  const m = d.getMonth();
32	  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
33	}
34	
35	export async function generate(input: {
36	  occasion: UiOccasion;
37	  formality: number | null;
38	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
39	  lean: string[];
40	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
41	  regenerate?: boolean;
42	  city?: { lat: number; lon: number; label: string; source: LocationSource };
43	}): Promise<GenerateResult> {
44	  try {
45	    const supabase = await createClient();
46	    const {
47	      data: { user },
48	    } = await supabase.auth.getUser();
49	    if (!user) return { status: "error", message: "Not signed in" };
50	
51	    const { data: profile } = await supabase
52	      .from("profiles")
53	      .select(
54	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source",
55	      )
56	      .eq("id", user.id)
57	      .single();
58	    const { data: itemsRaw } = await supabase
59	      .from("items")
60	      .select("*")
61	      .eq("user_id", user.id)
62	      .eq("archived", false);
63	    const items = itemsRaw ?? [];
64	    const byId = new Map(items.map((i) => [i.id, i]));
65	
66	    const loc = resolveLocation({ input: input.city, profile });
67	
68	    const now = new Date();
69	    const f = await fetchForecast(loc.lat, loc.lon);
70	    const advice = laterAdvice(f.hourly);
71	    const weather: WeatherPayload = {
72	      tempC: f.tempC,
73	      feelsLikeC: f.feelsLikeC,
74	      condition: f.condition,
75	      cityLabel: loc.label,
76	      timezone: f.timezone,
77	      locationOrigin: loc.origin,
78	      laterSentence: advice.sentence,
79	      adviceClause: advice.adviceClause,
80	      laterLabel: "Later",
81	      hourly: f.hourly,
82	    };
83	
84	    const today = localDateFor(now, f.timezone);
85	
86	    // The daily drop (Decision 5): today's looks are generated once and then
87	    // read back. Only an explicit regenerate spends an AI call on a day the
88	    // stylist has already answered.
89	    if (!input.regenerate) {
90	      const stored = await loadDailyLooks(user.id, input.occasion, today);
91	      if (stored?.length) {
92	        const paths = Array.from(
93	          new Set(
94	            stored
95	              .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
96	              .filter((it): it is NonNullable<typeof it> => Boolean(it))
97	              .map((it) => displayPath(it)),
98	          ),
99	        );
100	        const signed = await signItemImages(paths);
101	        const looks = reassembleLooks(stored, byId, signed, (id) => {
102	          const it = byId.get(id);
103	          return it ? displayPath(it) : undefined;
104	        });
105	        // null = the closet changed under the stored set; fall through and
106	        // regenerate rather than showing an outfit with a hole in it.
107	        if (looks) return { status: "ok", weather, looks };
108	      }
109	    }
110	
111	    await assertCanGenerate(user.id);
112	
113	    const candItems: CandidateItem[] = items.map((i) => ({
114	      id: i.id,
115	      category: i.category,
116	      colors: i.colors ?? [],
117	      formality: i.formality,
118	      seasons: i.seasons ?? [],
119	      material: i.material,
120	    }));
121	    // Occasion gives the context; the user's onboarding dress codes narrow it;
122	    // an explicit Refine formality overrides both.
123	    const band = applyFormalityOverride(
124	      personalBand(input.occasion, profile),
125	      input.formality,
126	    );
127	    const candidateArgs = {
128	      band,
129	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
130	      season: currentSeason(now),
131	      excludeItemIds: [],
132	      maxAccessories: 1,
133	    };
134	    const combos = buildCandidates(candItems, candidateArgs);
135	    if (combos.length === 0) {
136	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
137	    }
138	
139	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
140	    // The Refine colour pick lands here, in ranking — not in candidate building.
141	    // It reorders the shortlist toward the requested families and is dropped
142	    // silently when the closet cannot honour it.
143	    const top = rankTopN(combos, { aesthetic, band, lean: input.lean }, 20);
144	
145	    const { picks } = await rerank({
146	      combos: top.map((t) =>
147	        t.items.map((ci) => {
148	          const it = byId.get(ci.id)!;
149	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
150	        }),
151	      ),
152	      aesthetic,
153	      occasion: input.occasion,
154	      weatherLabel: f.condition,
155	      tempC: f.tempC,
156	    });
157	
158	    const paths = Array.from(
159	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
160	    );
161	    const signed = await signItemImages(paths);
162	
163	    const looks: Look[] = picks.map((p) => {
164	      const combo = top[p.combo_index]?.items ?? top[0].items;
165	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
166	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
167	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
168	        itemId: d.id,
169	        category: d.category,
170	        subcategory: d.subcategory ?? null,
171	        brand: d.brand ?? null,
172	        name: d.name ?? null,
173	        colors: d.colors ?? [],
174	        cutoutUrl: signed.get(displayPath(d)) ?? "",
175	        slot: slots[idx],
176	      }));
177	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
178	    });
179	
180	    // Fire-and-forget would be simpler, but a failed write means the user pays
181	    // for another AI call on their next tap — worth awaiting.
182	    await saveDailyLooks(user.id, input.occasion, today, weather, looks);
183	
184	    return { status: "ok", weather, looks };
185	  } catch (e) {
186	    console.error("[generate] failed:", e);
187	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
188	  }
189	}
190	
191	/**
192	 * The single write path for a user's location. `generate` stays read-only.
